import { useMemo } from 'react';

import { useBffData, useCurrentPage, usePageFilterStatus } from 'hooks';

import type {
  InnovationHubOverviewPageData,
  InnovationHubOverviewViewState,
} from '../../types';
import {
  BFF_VIEW_ID,
  getMainCards,
  getPortfolioBigNumbers,
  getPortfolioPieCharts,
} from '../../utils/overviewBffResponse';

export function useInnovationHubOverviewPageData(): InnovationHubOverviewPageData {
  const { currentPage } = useCurrentPage();
  const { isLoading: filtersLoading } = usePageFilterStatus(currentPage);
  const bffResult = useBffData({
    id: BFF_VIEW_ID,
    kpiGroup: 'innovation',
    skipRequest: filtersLoading,
  });

  const mainCards = useMemo(
    () => getMainCards(bffResult.data),
    [bffResult.data],
  );

  const view = useMemo((): InnovationHubOverviewViewState => {
    if (bffResult.loading) return 'loading';
    if (bffResult.error) return 'error';
    if (!mainCards || Object.keys(mainCards).length === 0) return 'empty';
    return 'ready';
  }, [bffResult.loading, bffResult.error, mainCards]);

  const portfolioBigNumbers = useMemo(
    () => getPortfolioBigNumbers(bffResult.data),
    [bffResult.data],
  );

  const portfolioPieCharts = useMemo(
    () => getPortfolioPieCharts(bffResult.data),
    [bffResult.data],
  );

  return {
    totalPerformance: {
      view,
      mainCards: view === 'ready' ? mainCards : null,
      refetch: bffResult.refetch,
    },
    portfolio: {
      bigNumbers: portfolioBigNumbers,
      pieCharts: portfolioPieCharts,
      loading: bffResult.loading,
      error: bffResult.error,
    },
  };
}
